            if(p is null||p.PlayerSeat!=0)Accept(g,new AdvanceOneStepCommand(g.Revision));else if(p.Kind==DecisionKind.PlayCard)End(g);else if(At(g,Watch)||At(g,Health))Continue(g);else if(p.Kind is DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification)Answer(g,c=>c.Cards.Count==0);else if(p.Kind==DecisionKind.RescueDying)Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"let-die"or"pass");else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Skip(g);else throw new InvalidOperationException($"Unexpected boundary {method}:{line}: "+Diagnostic(g));}
        throw new InvalidOperationException($"Missing boundary {method}:{line}: "+Diagnostic(g));
    }
